insert into public.chapters (chapter, title, scenarios) values (6, 'Master the Future: Planning and Goal Setting', '{}'::jsonb) on conflict (chapter) do update set title = excluded.title, scenarios = excluded.scenarios;

insert into public.questions (id, chapter, num, scenario, question, options, answer, marked, note, unsure) values
('c6-q01', 6, 1, null, 'Which one of the following is NOT a function of planning?', '["defining goals", "identifying a strategy for attaining goals", "settling disputes between employees", "coordinating organizational activities"]'::jsonb, 'C', 'C', null, false),
('c6-q02', 6, 2, null, 'In informal planning, goals are usually ________ shared with others in the organization.', '["written, but little is", "unwritten, and little is", "written, and much is", "unwritten, but much is"]'::jsonb, 'B', 'B', null, false),
('c6-q03', 6, 3, null, 'Informal planning is ________.', '["written and distributed to employees", "general and usually lacks continuity", "performed exclusively by middle managers", "more specific than formal planning"]'::jsonb, 'B', 'B', null, false),
('c6-q04', 6, 4, null, 'In formal planning, ________.', '["specific goals covering a period of years are defined", "to maximize flexibility, specific goals are never spelled out", "very broad general goals are developed", "goals may be written or unwritten"]'::jsonb, 'A', 'A', null, false),
('c6-q05', 6, 5, null, 'Which of the following is NOT a reason for managers to plan?', '["to give direction to an organization", "to deal with change", "to establish goals", "to establish responsibility for mistakes"]'::jsonb, 'D', 'D', null, false),
('c6-q06', 6, 6, null, 'Planning gives organizations direction that primarily helps them ________.', '["improve teamwork and coordinate activities", "improve their image in the business community", "improve morale of middle managers", "improve morale of all employees"]'::jsonb, 'A', 'A', null, false),
('c6-q07', 6, 7, null, 'Planning gives organizations a way to deal with change that ________.', '["eliminates all uncertainty", "reduces uncertainty", "reduces certainty", "increases ambiguity"]'::jsonb, 'B', 'B', null, false),
('c6-q08', 6, 8, null, 'Organizations that don''t formally plan may be more likely to have ________.', '["corrupt managers", "legal problems", "multiple departments performing the same task", "a single department carrying out all company functions"]'::jsonb, 'C', 'C', null, false),
('c6-q09', 6, 9, null, 'One effect of planning on managers is that it forces them to ________.', '["fear change", "anticipate and consider the effect of change", "work to prevent change", "ignore any change that doesn''t directly affect them"]'::jsonb, 'B', 'B', null, false),
('c6-q10', 6, 10, null, 'Managers who fail to plan may ________.', '["take advantage of change", "stimulate change", "be positively affected by change", "be adversely affected by change"]'::jsonb, 'D', 'D', null, false),
('c6-q11', 6, 11, null, 'Which one of the following is a frequently cited criticism of formal planning?', '["Plans lock organizations into rigid goals and timetables.", "Plans take too long to create.", "Plans create resentment within different levels of the organization.", "Formal planning works well only for smaller companies."]'::jsonb, 'A', 'A', null, false),
('c6-q12', 6, 12, null, 'One criticism of formal planning is that it focuses on how to beat the competition rather than how to ________.', '["have cordial relationships with the competition", "focus on new opportunities", "balance the organization''s budget", "cooperate with the competition"]'::jsonb, 'B', 'B', null, false),
('c6-q13', 6, 13, null, 'Failing to discard successful plans from the past is likely to lead to ________.', '["more success because conditions are unlikely to change in the future", "failure because conditions are likely to change in the future", "success because of the high quality of the plans", "failure because of the low quality of the plans"]'::jsonb, 'B', null, 'Not marked on the sheet. Criticism of planning: success can breed failure, because the environment changes.', false),
('c6-q14', 6, 14, null, 'Studies of performance in organizations that plan have reached ________ with respect to the benefits of formal planning.', '["somewhat negative conclusions", "no conclusion", "extremely negative conclusions", "generally positive conclusions"]'::jsonb, 'D', 'D', null, false),
('c6-q15', 6, 15, null, 'Studies of planning show that the key to successful planning is to make sure that the plans ________.', '["cover every possible detail", "are high in quality", "are exceedingly simple to follow", "are not shared with employees"]'::jsonb, 'B', 'B', null, false),
('c6-q16', 6, 16, null, 'In studies in which formal planning did not lead to higher performance, ________ usually the culprit.', '["unforeseen events in the environment were", "demanding employees were", "stubborn ownership was", "lack of communication was"]'::jsonb, 'A', 'A', null, false),
('c6-q17', 6, 17, null, 'In traditional goal setting, these individuals set goals.', '["top managers", "middle and low-level managers", "middle managers", "managers and employees"]'::jsonb, 'A', 'A', null, false),
('c6-q18', 6, 18, null, 'In traditional goal setting, as they work their way from top management to employees, goals are likely to ________.', '["become more clear", "be more rigorously followed", "be unchanged", "become more specific"]'::jsonb, 'D', 'D', null, false),
('c6-q19', 6, 19, null, 'In a means-ends chain, a goal at a lower level ________.', '["is the bridge to a goal at the next higher level", "is attained only after higher level goals are fulfilled", "is separate from the goal at the next higher level", "is ignored if goals at higher levels are attained"]'::jsonb, 'A', 'A', null, false),
('c6-q20', 6, 20, null, 'In management by objectives (MBO), goals ________.', '["must be easily accomplished", "are jointly determined by employees and managers", "are determined by top management", "are developed by employees"]'::jsonb, 'B', 'B', null, false),
('c6-q21', 6, 21, null, 'In addition to being made by both managers and employees, MBO goals must be ________.', '["nonspecific and open-ended with regard to time", "specific and open-ended with regard to time", "specific and include an explicit time limit", "nonspecific and include no time limit"]'::jsonb, 'C', 'C', null, false),
('c6-q22', 6, 22, null, 'MBO programs are usually largely successful because they ________.', '["give employees a sense of ownership of goals", "free managers from the responsibility of setting goals", "give managers a sense of ownership of goals", "free employees from responsibility if goals are not met"]'::jsonb, 'A', 'A', null, false),
('c6-q23', 6, 23, null, 'Which goal-setting sequence is correct for the following steps?
1. Evaluate resources.
2. Identify goals.
3. Review the mission and job tasks.
4. Communicate goals.
5. Link rewards to goals.
6. Build feedback mechanisms.', '["1, 2, 4, 6, 3, 5", "4, 2, 5, 3, 1, 6", "3, 4, 2, 6, 5, 1", "3, 1, 2, 4, 6, 5"]'::jsonb, 'D', 'D', null, false),
('c6-q24', 6, 24, null, 'The breadth of a plan refers to ________ concerns.', '["long-term versus short-term", "strategic versus tactical", "specific versus directional", "single use versus standing"]'::jsonb, 'B', 'B', null, false),
('c6-q25', 6, 25, null, 'The specificity of a plan refers to ________ concerns.', '["long-term versus short-term", "strategic versus tactical", "specific versus directional", "single use versus standing"]'::jsonb, 'C', 'C', null, false),
('c6-q26', 6, 26, null, 'Strategic plans address ________.', '["overall organizational goals", "goals for a single branch of the organization", "how overall goals are to be achieved", "how a single goal is to be achieved"]'::jsonb, 'A', 'A', null, false),
('c6-q27', 6, 27, null, 'Tactical plans are operational plans that identify ________.', '["overall organizational goals", "how overall goals are to be achieved", "the mission of an organization", "specific goals for accomplishing a specific objective"]'::jsonb, 'B', 'B', null, false),
('c6-q28', 6, 28, null, 'A politician whose ultimate goal is to get elected is planning campaign ads for TV. In planning the ads, the politician is functioning at a ________ level.', '["strategic", "long-term", "tactical", "directional"]'::jsonb, 'C', 'C', null, false),
('c6-q29', 6, 29, null, 'Directional plans ________.', '["leave no room for interpretation", "are flexible general guidelines", "are difficult to modify", "must be short-term plans"]'::jsonb, 'B', 'B', null, false),
('c6-q30', 6, 30, null, 'Standing plans typically can be used ________.', '["only once", "only in conjunction with specific, long-term plans", "twice at most", "repeatedly"]'::jsonb, 'D', null, 'Not marked on the sheet. Standing plans are ongoing plans that guide activities performed repeatedly.', false),
('c6-q31', 6, 31, null, 'Top managers, for the most part, focus on this type of planning.', '["operational", "strategic", "tactical", "short term"]'::jsonb, 'B', null, 'Not marked on the sheet.', false),
('c6-q32', 6, 32, null, 'The more uncertain a situation is, the more ________ plans must be.', '["unspecific", "long term", "flexible", "short term"]'::jsonb, 'C', null, 'Not marked on the sheet. Under high uncertainty, plans must be flexible (directional) – note the textbook also says plans should be more short-term; "flexible" is the best fit for this wording.', true),
('c6-q33', 6, 33, null, 'The commitment concept states that plans should ________.', '["always stake out a longer time period than is estimated", "always stake out a shorter time period than is estimated", "stake out a time period that is neither too long nor too short", "not include time periods because they are too confining"]'::jsonb, 'C', null, 'Not marked on the sheet. Commitment concept: plans should extend far enough to meet the commitments made today – too long or too short is inefficient/ineffective.', false),
('c6-q34', 6, 34, null, 'Most managers feel that formal, top-down plans created by corporate planning departments are ________.', '["very useful", "usually unsatisfactory", "very detailed", "excellent"]'::jsonb, 'B', null, 'Not marked on the sheet. Plans made by planning specialists were often ignored/unsatisfactory, so planning moved down to line managers.', false),
('c6-q35', 6, 35, null, 'In the twenty-first century, managers increasingly need to consider their plans as ________.', '["highly explicit recipes that must be scrupulously followed", "a vague philosophy that should not interfere with actions", "flexible road maps with destinations that may change", "rigid road maps with a single destination"]'::jsonb, 'C', null, 'Not marked on the sheet.', false),
('c6-q36', 6, 36, null, 'A cell phone company might ask managers to do some environmental scanning of blogs that deal with electronics as a way to ________.', '["obtain new customers", "identify emerging trends", "obtain new advertisers", "identify potential rivals"]'::jsonb, 'B', null, 'Not marked on the sheet. Environmental scanning = screening information to detect emerging trends.', false),
('c6-q37', 6, 37, null, 'Which one of the following is NOT something that a company would be likely to do as a part of a competitive intelligence program?', '["buy competitors'' products", "attend trade shows", "have employees evaluate competing products", "buy stock in a competitor''s company"]'::jsonb, 'D', null, 'Not marked on the sheet.', false),
('c6-q38', 6, 38, null, 'Formal planning typically leads to which one of the following?', '["higher profits", "lower productivity", "higher sales, but lower profits", "tension between different management levels"]'::jsonb, 'A', null, 'Not marked on the sheet. Formal planning is generally associated with positive financial results (higher profits, return on assets).', false),
('c6-q39', 6, 39, null, 'Which one of the following defines the time frame of a long-term plan?', '["over seven years", "over three years", "under three years", "over one year"]'::jsonb, 'B', null, 'Not marked on the sheet. Textbook: long-term plans have a time frame beyond three years; short-term plans one year or less.', false),
('c6-q40', 6, 40, null, 'Planning is concerned with ________.', '["both ends and means", "ends only", "means only", "neither ends nor means"]'::jsonb, 'A', null, 'Not marked on the sheet. Planning is concerned with ends (what) and means (how).', false)
on conflict (id) do update set scenario = excluded.scenario, question = excluded.question, options = excluded.options, answer = excluded.answer, marked = excluded.marked, note = excluded.note, unsure = excluded.unsure;

insert into public.open_questions (id, chapter, num, question, model_answer) values
('c6-o1', 6, 1, 'In a short essay, compare strategic plans and tactical plans.', 'Strategic plans apply to the entire organization and establish its overall goals; they are made mainly by top managers, usually cover a longer time frame (often 3+ years) and are broad. Example: "become the market leader in Asia by 2030."

Tactical (operational) plans specify how the overall goals are to be achieved: they are made mainly by middle and lower-level managers, cover a narrower part of the organization (a department or function), have a shorter time frame and are more detailed/specific. Example: the marketing department''s quarterly ad campaign that supports the strategic goal.

The difference is breadth (strategic vs. tactical); both must be linked through a means-ends chain so that tactical plans serve as the means to reach strategic ends.'),
('c6-o2', 6, 2, 'In a short essay, define and discuss management by objectives (MBO).', 'Management by objectives (MBO) is a process of setting mutually agreed-upon goals and using those goals to evaluate employee performance.

Key elements:
1. Goal specificity – goals are specific and measurable.
2. Participative decision making – managers and employees set goals jointly (not top-down only).
3. Explicit time period – each goal has a deadline.
4. Performance feedback – continuous feedback on progress toward goals.

Goals cascade through the organization, so individual goals support unit and organizational goals (means-ends chain).

Why it works: employees feel a sense of ownership of goals and are more motivated; studies show MBO can increase performance and productivity, especially with top-management commitment. Limitations: it is less effective in dynamic environments where goals constantly change, it can over-emphasize individual goals at the expense of teamwork, and it can become a paperwork exercise.')
on conflict (id) do update set question = excluded.question, model_answer = excluded.model_answer;
